trait Sym<R> {
    fn lit(&self, i: i64) -> R;
    fn add(&self, a: R, b: R) -> R;
}

fn exp<R, S: Sym<R>>(s: &S) -> R { s.add(s.lit(1), s.add(s.lit(2), s.lit(4))) }

struct Eval;
impl Sym<i64> for Eval {
    fn lit(&self, i: i64) -> i64 { i }
    fn add(&self, a: i64, b: i64) -> i64 { a + b }
}
